ruleToc.chapterList:
@webjs:
(function () {
  var els = document.querySelectorAll('.comics-chapters__item');
  if (!els || els.length === 0) return null;
  var map = {}, order = [];
  for (var i = 0; i < els.length; i++) {
    var h = els[i].getAttribute('href') || '';
    var mi = h.match(/comic_id=([^&]+)/);
    var ms = h.match(/chapter_slot=(\d+)/);
    if (!mi || !ms) continue;
    var slot = parseInt(ms[1], 10);
    if (map[slot]) continue;
    var name = (els[i].textContent || '').replace(/\s+/g, ' ').trim();
    if (!name) continue;
    map[slot] = {
      chapterName: name,
      chapterUrl: 'https://tw.bzmgcn.com/comic/chapter/' + mi[1] + '/0_' + slot + '.html'
    };
    order.push(slot);
  }
  order.sort(function (a, b) { return a - b; });
  var out = [];
  for (var k = 0; k < order.length; k++) out.push(map[order[k]]);
  return JSON.stringify(out);
})()
